    InternalTestNginx = 'nginx/uten-imp-internal-test.conf.example'
    InternalTestGuide = 'internal-test-runtime.zh-CN.md'
    InternalTestOnboardingGuide = 'setup/EXISTING_TEST_HOST_INTERNAL_TEST_ONBOARDING.zh-CN.md'
