    NvmeEarlyResumeUnit = 'systemd/uten-imp-nvme-commissioning-resume.service.example'
    NvmeLateResumeUnit = 'systemd/uten-imp-nvme-commissioning-late-resume.service.example'
    NvmeLateResumeTimer = 'systemd/uten-imp-nvme-commissioning-late-resume.timer.example'
    NvmeGateAuthorizerUnit = 'systemd/uten-imp-nvme-gate-authorizer.service.example'
    NvmeActiveTransactionGate = 'systemd/uten-imp-nvme-active-transaction-gate.conf.example'
    WebsiteInquiryController = '../server/src/main/java/com/uten/imp/features/webinquiry/WebsiteInquiryController.java'
    AttachmentController = '../server/src/main/java/com/uten/imp/features/attachment/AttachmentController.java'
