$text = @{}
foreach ($entry in $paths.GetEnumerator()) {
    $path = Join-Path $PSScriptRoot $entry.Value
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Missing deployment file: $($entry.Key) ($path)"
    }
    $text[$entry.Key] = Get-Content -LiteralPath $path -Raw -Encoding UTF8
}

$repoRoot = Split-Path -Parent $PSScriptRoot
$workflowPath = Join-Path $repoRoot '.github/workflows/release.yml'
$oidcAcceptanceWorkflowPath = Join-Path $repoRoot '.github/workflows/aliyun-oidc-acceptance.yml'
$webIndexPath = Join-Path $repoRoot 'web/index.html'
$webUpdatePath = Join-Path $repoRoot 'web/update_check.js'
$websiteConfigPath = Join-Path $repoRoot 'website/next.config.mjs'
$websiteAssemblerPath = Join-Path $repoRoot 'website/deploy/assemble-release.mjs'
$websiteRuntimeValidatorPath = Join-Path $repoRoot 'website/deploy/validate-runtime.sh'
$releaseSecurityTestPath = Join-Path $repoRoot 'deploy/updater/test_release_security.py'
$ossEnvTestPath = Join-Path $repoRoot 'deploy/updater/test_validate_oss_pull_env.py'
foreach ($path in @($workflowPath, $oidcAcceptanceWorkflowPath, $webIndexPath, $webUpdatePath, $websiteConfigPath, $websiteAssemblerPath, $websiteRuntimeValidatorPath, $releaseSecurityTestPath, $ossEnvTestPath)) {
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Missing cross-stack deployment file: $path"
    }
}
$workflow = Get-Content -LiteralPath $workflowPath -Raw -Encoding UTF8
$oidcAcceptanceWorkflow = Get-Content -LiteralPath $oidcAcceptanceWorkflowPath -Raw -Encoding UTF8
$webIndex = Get-Content -LiteralPath $webIndexPath -Raw -Encoding UTF8
$webUpdate = Get-Content -LiteralPath $webUpdatePath -Raw -Encoding UTF8
$websiteConfig = Get-Content -LiteralPath $websiteConfigPath -Raw -Encoding UTF8
$websiteAssembler = Get-Content -LiteralPath $websiteAssemblerPath -Raw -Encoding UTF8
$websiteRuntimeValidator = Get-Content -LiteralPath $websiteRuntimeValidatorPath -Raw -Encoding UTF8

function Assert-Contains {
    param([string] $Value, [string] $Expected, [string] $Label)
    if (-not $Value.Contains($Expected)) {
        throw "Missing deployment contract: $Label"
    }
}

function Assert-NotContains {
    param([string] $Value, [string] $Forbidden, [string] $Label)
    if ($Value.Contains($Forbidden)) {
        throw "Forbidden deployment contract: $Label"
    }
}

function Assert-Regex {
    param([string] $Value, [string] $Pattern, [string] $Label)
    if (-not [regex]::IsMatch($Value, $Pattern)) {
        throw "Missing deployment pattern: $Label"
    }
}

# Dedicated internal ERP test profile: production-like network/secrets/runtime
# boundaries with one fixed NVMe local-storage exception. Production/cloud OSS
# contracts below remain independent and unchanged.
$internalProfile = $text.InternalTestProfile
Assert-Contains $internalProfile 'address: 127.0.0.1' 'internal-test loopback backend'
Assert-Contains $internalProfile 'lazy-initialization: false' 'internal-test global lazy initialization disabled'
Assert-Contains $internalProfile 'enabled: false' 'internal-test runtime Flyway and external features closed'
Assert-Contains $internalProfile 'require-https: true' 'internal-test application HTTPS requirement'
Assert-Contains $internalProfile 'swagger-enabled: false' 'internal-test Swagger disabled'
Assert-Contains $internalProfile 'provider: local' 'internal-test local attachment provider'
Assert-Contains $internalProfile 'uploads-enabled: false' 'internal-test attachment intake disabled'
Assert-Contains $internalProfile 'local-dir: /data/uten-imp/attachments' 'fixed internal-test NVMe attachment path'
Assert-NotContains $internalProfile 'UTEN_STORAGE_LOCAL_DIR' 'overrideable internal-test attachment path'
Assert-NotContains $internalProfile 'UTEN_OSS_' 'internal-test OSS credential/config surface'
Assert-Contains $text.InternalTestGate 'internal-test must be the only active Spring profile' 'exclusive internal-test profile gate'
Assert-Contains $text.InternalTestGate 'prod}/{@code cloud}' 'independent production storage gate documentation'
Assert-Contains $text.InternalTestEnv 'UTEN_PROFILE=internal-test' 'internal-test environment identity'
Assert-Contains $text.InternalTestEnvValidator 'expect_exact SPRING_FLYWAY_ENABLED false' 'internal-test runtime Flyway validator'
Assert-Contains $text.InternalTestEnvValidator '#!/bin/bash' 'internal-test fixed shell interpreter'
Assert-Contains $text.InternalTestEnvValidator 'expect_exact UTEN_STORAGE_LOCAL_DIR /data/uten-imp/attachments' 'internal-test environment fixed storage path'
Assert-Contains $text.InternalTestEnvValidator 'validate_supported_environment_keys' 'internal-test environment key allowlist'
Assert-Contains $text.InternalTestEnvValidator 'unsupported environment key:' 'internal-test unknown environment key refusal'
Assert-Contains $text.InternalTestEnvValidator 'ipaddress.ip_network(raw, strict=True)' 'internal-test canonical CIDR parser'
Assert-Contains $text.InternalTestEnvValidator 'network.prefixlen > parent.prefixlen' 'internal-test strict private subnet requirement'
Assert-NotContains $text.InternalTestEnv 'SPRING_MAIN_LAZY_INITIALIZATION' 'internal-test lazy-init environment override surface'
if ([regex]::IsMatch($text.InternalTestEnvValidator, '(?m)^\s*source\s')) {
    throw 'Forbidden deployment contract: internal-test environment shell execution'
}
Assert-NotContains $text.InternalTestEnvValidator 'eval ' 'internal-test environment eval execution'
Assert-Contains $text.InternalTestStorageValidator 'capacity_bytes >= 300 * 1024 * 1024 * 1024' 'internal-test minimum NVMe data capacity'
Assert-Contains $text.InternalTestStorageValidator '-o ROTA "$source_device"' 'internal-test non-rotational storage check'
Assert-NotContains $text.InternalTestStorageValidator 'mkfs' 'storage preflight filesystem mutation'
Assert-Contains $text.InternalTestUnit '-Dspring.profiles.active=internal-test' 'systemd pins internal-test profile'
Assert-Contains $text.InternalTestUnit '-Dspring.main.lazy-initialization=false' 'systemd pins eager internal-test safety gate'
Assert-Contains $text.InternalTestUnit 'ExecStartPre=+/bin/bash --noprofile --norc -p /usr/local/sbin/uten-imp-validate-internal-test-server-env' 'systemd invokes validator through fixed privileged shell mode'
Assert-Contains $text.InternalTestUnit 'UnsetEnvironment=LD_PRELOAD LD_LIBRARY_PATH LD_AUDIT LD_DEBUG GCONV_PATH BASH_ENV ENV SHELLOPTS BASHOPTS PS4 BASH_XTRACEFD' 'systemd strips pre-validator loader and shell controls'
Assert-Contains $text.InternalTestUnit 'JAVA_TOOL_OPTIONS JDK_JAVA_OPTIONS _JAVA_OPTIONS' 'systemd strips Java option injection'
Assert-Contains $text.InternalTestUnit 'SPRING_APPLICATION_JSON SPRING_CONFIG_LOCATION SPRING_CONFIG_ADDITIONAL_LOCATION SPRING_MAIN_LAZY_INITIALIZATION' 'systemd strips Spring control injection'
Assert-Contains $text.InternalTestUnit '-Dspring.flyway.enabled=false' 'systemd pins Flyway disabled'
Assert-Contains $text.InternalTestUnit 'ReadWritePaths=/data/uten-imp/attachments -/run/uten-imp-release' 'systemd fixed local attachment write boundary'
Assert-Contains $text.InternalTestUnit 'IPAddressDeny=any' 'internal-test outbound network deny'
Assert-Contains $text.InternalTestUnit 'IPAddressAllow=localhost' 'internal-test loopback database allowance'
Assert-Contains $text.InternalTestNginx 'server_name __INTERNAL_DOMAIN__;' 'internal-test internal DNS placeholder'
Assert-Contains $text.InternalTestNginx 'ssl_reject_handshake on;' 'internal-test unknown SNI refusal'
Assert-Contains $text.InternalTestNginx 'allow __EXACT_OFFICE_CIDR__;' 'internal-test exact office CIDR'
Assert-Contains $text.InternalTestNginx 'location ~ ^/api/website-inquiries(?:;[^/]*)?/ingest(?:[;/]|$) {' 'external website ingest excluded from ERP host'
Assert-Contains $text.InternalTestNginx 'location ~ ^/api/attachments(?:;[^/]*)?/(?:presign|confirm)(?:[;/]|$) {' 'attachment presign and confirm intake excluded'
Assert-Contains $text.InternalTestNginx 'location ~ ^/api/attachments(?:;[^/]*)?/raw(?:[;/]|$) {' 'attachment raw upload method gate'
Assert-Contains $text.InternalTestNginx 'limit_except GET HEAD {' 'internal-test attachment mutation refusal'
Assert-Contains $text.InternalTestNginx 'Attachment uploads are a three-step protocol: presign, raw PUT, confirm.' 'attachment upload protocol gate'
$internalInquiryLocations = [regex]::Matches($text.InternalTestNginx, '(?m)^\s*location\s+[^\{]*?/api/website-inquiries[^\{]*\{')
if ($internalInquiryLocations.Count -ne 1) {
    throw 'Forbidden deployment contract: website ingest must have exactly one Nginx location'
}
$internalAttachmentLocations = [regex]::Matches($text.InternalTestNginx, '(?m)^\s*location\s+[^\{]*?/api/attachments[^\{]*\{')
if ($internalAttachmentLocations.Count -ne 2) {
    throw 'Forbidden deployment contract: attachment intake must have exactly two reviewed Nginx locations'
}
if (([regex]::Matches($text.WebsiteInquiryController, '@(?:Get|Post|Put|Patch|Delete)Mapping')).Count -ne 6) {
    throw 'Forbidden deployment contract: website inquiry Controller route inventory changed without gateway review'
}
# 9 -> 11（2026-09-11）：GET /{id}/preview 与 PUT /{id}/category。已按本闸门的用意
# 复核网关策略——两条都落在通用 location /api/（不限方法、同一限流区），
# 不需要像 presign/confirm（内网部署一律 404）或 raw（只放行 GET/HEAD）那样单开 location；
# 因此上面「恰好两个已评审的 attachment location」的计数保持 2 不变。
if (([regex]::Matches($text.AttachmentController, '@(?:Get|Post|Put|Patch|Delete)Mapping')).Count -ne 11) {
    throw 'Forbidden deployment contract: attachment Controller route inventory changed without gateway review'
}
Assert-Contains $text.InternalTestGuide '<!-- INTERNAL-TEST-SINGLE-NVME-NOT-PRODUCTION -->' 'internal-test production boundary'
Assert-Contains $text.InternalTestOnboardingGuide 'dataClassification=discardable-test-only' 'internal-test onboarding discardable-data boundary'
Assert-Contains $text.InternalTestOnboardingGuide 'productionAuthority=false' 'internal-test onboarding non-production authority'
Assert-Contains $text.InternalTestOnboardingGuide 'COMMITTED_STORAGE_ONLY_LIVE_VERIFIED' 'internal-test onboarding storage late-finalization prerequisite'
Assert-Contains $text.InternalTestOnboardingGuide 'mutation-authorized.committed.json' 'internal-test host preparation terminal authority'
Assert-Contains $text.InternalTestOnboardingGuide 'active-pointer.committed.json' 'internal-test database terminal pointer'
Assert-Contains $text.InternalTestOnboardingGuide '--first-release' 'internal-test explicit first activation'
Assert-Contains $text.InternalTestOnboardingGuide '--enable-on-boot' 'internal-test explicit boot enablement'
Assert-Contains $text.InternalTestOnboardingGuide '--approve-database-change' 'internal-test onboarding rejects manual database boolean'
Assert-Contains $text.InternalTestOnboardingGuide '<!-- INTERNAL-TEST-NEW-MIGRATION-HARD-NO-GO -->' 'internal-test new migration hard stop'
Assert-NotContains $text.InternalTestOnboardingGuide '192.168.' 'internal-test onboarding topology redaction'

# Even the legacy HTTP template must remain topology-free because source
# snapshots can include it. Live values belong only in ignored private handoff.
Assert-Contains $text.LegacyLanNginx 'server_name __INTERNAL_DOMAIN__ _;' 'legacy LAN DNS placeholder'
Assert-Contains $text.LegacyLanNginx 'allow __EXACT_OFFICE_CIDR__;' 'legacy LAN CIDR placeholder'
if ([regex]::IsMatch($text.LegacyLanNginx, '(?m)^\s*server_name\s+(?:\d{1,3}\.){3}\d{1,3}')) {
    throw 'Forbidden deployment contract: legacy LAN template contains a raw server address'
}

# On-prem Nginx: exact TLS boundary, loopback backend/probe, bounded imports.
$nginx = $text.Nginx
Assert-Contains $nginx 'server 127.0.0.1:8080;' 'loopback backend'
Assert-Contains $nginx 'listen 127.0.0.1:8081;' 'loopback Web probe'
Assert-Contains $nginx 'location = /version.json {' 'signed live-version endpoint'
Assert-Contains $nginx 'listen 80 default_server;' 'unknown Host HTTP reject vhost'
Assert-Contains $nginx 'listen 443 ssl default_server;' 'unknown SNI TLS reject vhost'
Assert-Contains $nginx 'ssl_reject_handshake on;' 'unknown SNI handshake rejection'
Assert-Regex $nginx '(?m)^\s*ssl_protocols TLSv1\.2 TLSv1\.3;\s*$' 'explicit modern TLS protocol policy'
Assert-Contains $nginx 'ssl_session_tickets off;' 'stateless TLS ticket rejection'
Assert-Contains $nginx "ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305';" 'reviewed TLS 1.2 ciphers'
Assert-Contains $nginx 'if ($host != "__LOCAL_DOMAIN__") { return 444; }' 'fixed configured Host enforcement'
Assert-Contains $nginx 'return 308 https://__LOCAL_DOMAIN__$request_uri;' 'non-reflective HTTPS redirect'
Assert-Contains $nginx 'allow __OFFICE_CIDR__;' 'exact office CIDR placeholder'
Assert-Contains $nginx 'allow __VPN_CIDR__;' 'exact VPN CIDR placeholder'
Assert-Contains $nginx 'location ~ ^/api/master/goods/import/(?:detect|commit)$ {' 'exact goods-import boundary'
Assert-Contains $nginx 'client_max_body_size 10m;' 'goods-import transport cap'
Assert-Contains $nginx 'limit_conn uten_goods_import_conn 2;' 'goods-import per-IP concurrency cap'
Assert-Contains $nginx 'root /opt/uten-imp/current/web;' 'immutable Web symlink root'
Assert-NotContains $nginx 'allow 10.0.0.0/8;' 'broad RFC1918 allow rule'
Assert-NotContains $nginx 'allow 192.168.0.0/16;' 'broad office allow rule'
$exactHealth = $nginx.IndexOf('location = /actuator/health {')
$probeHealth = $nginx.IndexOf('location ~ ^/actuator/health/(?:liveness|readiness)$ {')
$actuatorDeny = $nginx.IndexOf('location /actuator/ {')
$spaFallback = $nginx.LastIndexOf('location / {')
if ($exactHealth -lt 0 -or $probeHealth -lt 0 -or $actuatorDeny -lt 0 -or $spaFallback -lt 0 -or
    $actuatorDeny -lt $exactHealth -or $actuatorDeny -lt $probeHealth -or $actuatorDeny -gt $spaFallback) {
    throw 'Actuator allow/deny and SPA fallback ordering is unsafe'
}
if (([regex]::Matches($nginx, [regex]::Escape('{'))).Count -ne
    ([regex]::Matches($nginx, [regex]::Escape('}'))).Count) {
    throw 'Nginx template braces are unbalanced'
}

# App and watchdog services: data/DB hard gates, bounded memory, root-owned probes.
$appUnit = $text.AppUnit
Assert-Contains $appUnit 'RequiresMountsFor=/data' 'data mount systemd hard dependency'
Assert-Contains $appUnit 'Requires=postgresql@16-main.service' 'PostgreSQL service dependency'
Assert-Contains $appUnit 'BindsTo=data.mount postgresql@16-main.service' 'data and database disappearance binding'
Assert-Contains $appUnit 'RestartSteps=5' 'systemd bounded restart backoff steps'
Assert-Contains $appUnit 'RestartMaxDelaySec=60s' 'systemd restart backoff ceiling'
Assert-Contains $appUnit 'StartLimitIntervalSec=10min' 'restart-storm observation window'
Assert-Contains $appUnit 'StartLimitBurst=8' 'restart-storm bounded burst'
Assert-Contains $appUnit 'ExecStartPre=/usr/bin/mountpoint --quiet /data' 'runtime mountpoint guard'
Assert-Contains $appUnit 'ExecStartPre=+/usr/bin/test ! -e /var/lib/uten-imp-release/activation-failed.json' 'persistent failed-activation boot gate'
Assert-Contains $appUnit 'ExecStartPre=+/usr/bin/test ! -e /var/lib/uten-imp-release/boot-enablement-in-progress.json' 'partial boot-enablement gate'
Assert-Contains $appUnit 'ExecStartPre=+/usr/bin/python3 -I /usr/local/libexec/uten-imp-release/runtime_boot_verifier.py' 'signed release/database/storage runtime boot gate'
Assert-Contains $appUnit 'TimeoutStartSec=120s' 'bounded runtime-verification startup deadline'
Assert-Contains $appUnit 'ReadWritePaths=-/run/uten-imp-release' 'one-use activation authorization consume boundary'
Assert-Contains $appUnit '-Dserver.address=127.0.0.1' 'JVM loopback bind'
Assert-Contains $appUnit '-Dspring.flyway.enabled=false' 'backend Flyway hard disable'
Assert-Contains $appUnit '-Xmx4g' 'JVM heap ceiling'
Assert-Contains $appUnit 'MemoryHigh=5G' 'cgroup memory throttle'
Assert-Contains $appUnit 'MemoryMax=6G' 'cgroup memory ceiling'
Assert-NotContains $appUnit 'ReadWritePaths=/data/uten-imp/attachments' 'OSS production JVM data-RAID write grant'
$migratorUnit = $text.MigratorUnit
Assert-Contains $migratorUnit 'Type=oneshot' 'migration-only oneshot unit'
Assert-Contains $migratorUnit 'User=uten-imp-migrate' 'dedicated migration identity'
Assert-Contains $migratorUnit 'Group=uten-imp-migrate' 'dedicated migration group'
Assert-Contains $migratorUnit 'EnvironmentFile=/etc/uten-imp-migrator/migrator.env' 'isolated migration credential file'
Assert-Contains $migratorUnit 'ExecStartPre=+/usr/local/sbin/uten-imp-validate-migrator-env /etc/uten-imp-migrator/migrator.env' 'root migration-env validation'
Assert-Contains $migratorUnit '/opt/uten-imp/current/server/uten-imp-migrator.jar' 'dedicated migration artifact'
Assert-Contains $migratorUnit 'IPAddressDeny=any' 'migration network deny baseline'
Assert-Contains $migratorUnit 'IPAddressAllow=localhost' 'migration loopback-only database access'
Assert-Contains $migratorUnit 'Restart=no' 'migration is never an auto-restarting daemon'
Assert-NotContains $migratorUnit 'WantedBy=' 'migration job never starts automatically at boot'
Assert-Contains $migratorUnit 'After=network-online.target data.mount postgresql@16-main.service' 'migrator ordering-only database and data dependencies'
Assert-Contains $migratorUnit 'Wants=network-online.target' 'migrator only pulls the network-online target'
Assert-NotContains $migratorUnit 'Requires=postgresql@16-main.service' 'migrator must not pull PostgreSQL online'
Assert-NotContains $migratorUnit 'RequiresMountsFor=/data' 'migrator must not pull the data mount online'
Assert-Contains $text.WatchdogUnit '/usr/local/libexec/uten-imp/uten-imp-watchdog' 'root-owned backend watchdog executable'
Assert-Contains $text.EntryWatchdogUnit '/usr/local/libexec/uten-imp/uten-imp-entry-watchdog' 'root-owned entry watchdog executable'
Assert-Contains $text.EntryWatchdogUnit 'After=network-online.target nginx.service' 'entry probe orders after Nginx without starting it'
Assert-Contains $text.EntryWatchdogUnit 'Wants=network-online.target' 'entry probe requests only network-online'
Assert-NotContains $text.EntryWatchdogUnit 'Wants=network-online.target nginx.service' 'entry probe never pulls intentionally disabled or stopped Nginx'
Assert-Contains $text.WatchdogUnit 'ExecStartPre=/usr/bin/test ! -e /var/lib/uten-imp-release/boot-enablement-in-progress.json' 'backend watchdog partial boot gate'
Assert-Contains $text.EntryWatchdogUnit 'ExecStartPre=/usr/bin/test ! -e /var/lib/uten-imp-release/boot-enablement-in-progress.json' 'entry watchdog partial boot gate'
foreach ($marker in @('activation-in-progress.json', 'recovery-in-progress.json')) {
    Assert-Contains $text.WatchdogUnit "ExecStartPre=/usr/bin/test ! -e /var/lib/uten-imp-release/$marker" "backend watchdog $marker transaction gate"
    Assert-Contains $text.EntryWatchdogUnit "ExecStartPre=/usr/bin/test ! -e /var/lib/uten-imp-release/$marker" "entry watchdog $marker transaction gate"
}
Assert-NotContains $text.WatchdogUnit '/opt/uten-imp/current/deploy/' 'release-controlled root watchdog'
