Assert-Contains $text.Phase1b 'ExecStart=/usr/sbin/sshd -D $SSHD_OPTS' 'audited ssh.service ExecStart contract'
Assert-Contains $text.Phase1b 'ssh.socket is active; migrate to audited ssh.service mode first' 'ssh.socket activation refusal'
Assert-Contains $text.Phase1b '(proc / "cmdline").read_bytes()' 'live ssh.service argv binding'
Assert-Contains $text.Phase1b '(proc / "environ").read_bytes()' 'live ssh.service environment binding'
Assert-Contains $text.Phase1b '0::{expected_cgroup}' 'live ssh.service cgroup binding'
Assert-Contains $text.Phase1b 'foreign sshd listener' 'additional sshd listener refusal'
Assert-Contains $text.Phase1b 'pids != {expected_pid}' 'TCP/22 listener exact MainPID binding'
Assert-Regex $text.Phase1b '(?s)install -d -o 0 -g 0 -m 0755 "\$CONFIG_DIR".*?fsync_path /etc/ssh.*?install -d -o 0 -g 0 -m 0755 "\$AUTHORIZED_KEYS_DIR".*?fsync_path /etc/ssh.*?atomic_install "\$transaction_dir/new-keys"' 'SSH trust directories are durable before key publication'
Assert-Regex $text.Phase1b '(?s)install -d -o 0 -g 0 -m 0700 "\$transaction_dir".*?fsync_path "\$transaction_dir".*?fsync_path "\$TRANSACTION_ROOT".*?atomic_install "\$transaction_dir/in-progress-candidate" "\$IN_PROGRESS"' 'transaction directory is durable before in-progress publication'
Assert-Regex $text.Phase1b '(?s)restore_transaction_file "\$transaction_dir" config.*?/usr/sbin/sshd -t \|\| return 1.*?restored effective sshd configuration differs from preimage.*?systemctl reload ssh\.service \|\| return 1.*?verify_live_ssh_runtime_contract \|\| return 1.*?restore_transaction_file "\$transaction_dir" keys.*?restore_transaction_file "\$transaction_dir" complete.*?atomic_remove "\$IN_PROGRESS" \|\| return 1' 'rollback activates the safe preimage policy before restoring keys and clearing its gate'
$rollbackMatch = [regex]::Match($text.Phase1b, '(?ms)^rollback_transaction\(\) \{(?<body>.*?)^\}')
if (-not $rollbackMatch.Success) {
    throw 'Missing deployment contract: rollback transaction body'
}
$rollbackBody = $rollbackMatch.Groups['body'].Value
$rollbackSteps = @(
    'restore_transaction_file "$transaction_dir" config "$CONFIG_PATH" || return 1',
    'systemctl reload ssh.service || return 1',
    'restore_transaction_file "$transaction_dir" keys "$AUTHORIZED_KEYS_DIR/$admin_user" || return 1',
    'restore_transaction_file "$transaction_dir" complete "$COMPLETE" || return 1',
    'atomic_remove "$IN_PROGRESS" || return 1'
)
$previousRollbackStep = -1
foreach ($rollbackStep in $rollbackSteps) {
    if (([regex]::Matches($rollbackBody, [regex]::Escape($rollbackStep))).Count -ne 1) {
        throw "Unsafe rollback contract: expected exactly one step: $rollbackStep"
    }
    $rollbackStepIndex = $rollbackBody.IndexOf($rollbackStep, [System.StringComparison]::Ordinal)
    if ($rollbackStepIndex -le $previousRollbackStep) {
        throw 'Unsafe rollback contract: configuration must be activated before keys are restored'
    }
    $previousRollbackStep = $rollbackStepIndex
}
