$retentionPolicy = $text.RetentionPolicy | ConvertFrom-Json
if ($retentionPolicy.keepVerifiedCandidates -lt 3 -or $retentionPolicy.keepVerifiedInstalled -lt 3) {
    throw 'Retention example must keep at least three verified candidates and installed releases'
}
if ($retentionPolicy.stagingProjectId -eq $retentionPolicy.installedProjectId) {
    throw 'Retention example must use distinct staging and installed project IDs'
}

# Phase4 must remain install-only until storage retention/quota/alerts exist.
$phase4 = $text.Phase4
