Assert-Contains $phase4 '-m pip uninstall --yes pip' 'updater runtime has no package installer'
Assert-Contains $phase4 'runuser -u uten-imp-updater' 'unprivileged dependency build and candidate inspection'
Assert-Contains $phase4 'operation lock must be root:uten-imp-updater 0660 with one hard link' 'fixed root-owned shared lock'
Assert-Contains $phase4 '"$ROOT_STATE/recovery-evidence" "$ROOT_STATE/database-receipts"' 'root-only recovery evidence directories'
Assert-Contains $phase4 'uten-imp-recover.sh" /usr/local/sbin/uten-imp-recover' 'root recovery wrapper installation'
Assert-Contains $phase4 'STABLE_DB_RECOVERY_VERIFIER=/usr/local/libexec/uten-imp-release/database_recovery_verifier.py' 'fixed database recovery verifier install path'
Assert-Contains $phase4 'installed {name} digest differs from updater policy' 'database/runtime verifier digest pin'
Assert-Contains $phase4 'runtime boot verifier {name} dependency digest is stale' 'runtime verifier dependency digest pin'
Assert-Contains $phase4 '"$UPDATER_SOURCE/retention_manager.py" "$new_updater/retention_manager.py"' 'Phase 4 preserves installed retention manager'
Assert-Contains $phase4 'ordinary reinstall may not collapse trust' 'signing-key rotation overlap guard'
Assert-Contains $phase4 'ssl_reject_handshake on;' 'expanded TLS catch-all audit'
Assert-Contains $phase4 '--enable-staging is intentionally NO-GO' 'staging fail-closed until retention'
Assert-Contains $phase4 'STAGING_NOT_ENABLED' 'default install-only outcome'
Assert-NotContains $phase4 'pip install --quiet --no-cache-dir oss2' 'legacy root online pip install'
Assert-NotContains $phase4 'uten-imp-http-lan.conf' 'legacy plaintext LAN site installation'
Assert-Contains $phase4 'pre-existing updater credential/config/state requires the audited retirement helper' 'legacy downloader credential/config/state rejection'
Assert-Contains $phase4 '/usr/local/sbin/uten-imp-validate-migrator-env /etc/uten-imp-migrator/migrator.env' 'phase4 migrator environment preflight'
Assert-Contains $phase4 'installed migrator unit differs from the reviewed phase3 template' 'phase4 fixed migrator unit contract'
Assert-Contains $phase4 'installed application unit differs from the reviewed phase3 template' 'phase4 fixed application unit contract'
Assert-Contains $phase4 'uten-imp-migrate.service' 'phase4 migrator inactivity and disable gate'
Assert-Contains $phase4 'stable privileged release guard differs from the reviewed Phase 4 source' 'stable verifier byte parity gate'
Assert-Contains $phase4 'Phase 4 release key differs from the independently bootstrapped stable trust policy' 'stable-to-updater key parity gate'
Assert-NotContains $phase4 'chown root:uten-imp /etc/uten-imp/oss-pull.env' 'legacy application-readable downloader credential installation'

# PostgreSQL repo2, continuous WAL, external alert and PITR acceptance boundaries.
Assert-Contains $text.BackupReadme '<!-- REAL-REPO2-WORM-PITR-ALERTS-NO-GO -->' 'repo2 source-only NO-GO'
Assert-Contains $text.BackupReadme '<!-- CURRENT-ERP-TEST-SERVER-SCOPE-20260812 -->' 'backup schedule current test-host scope'
Assert-Contains $text.Repo2Renderer 'render-candidate never writes under /etc' 'repo2 renderer cannot install active config'
Assert-Contains $text.Repo2Renderer 'WORM evidence SHA-256 differs from the out-of-band approved digest' 'WORM out-of-band digest binding'
Assert-Contains $text.Repo2Renderer 'active WORM evidence differs from the approved digest' 'active WORM read-back digest gate'
Assert-Contains $text.Repo2Renderer 'active repo2 config exact key set differs from the renderer' 'active repo2 semantic config gate'
Assert-Contains $text.Repo2Renderer 'repo2-storage-verify-tls=y' 'repo2 TLS verification'
Assert-Contains $text.BackupHealth 'restore points are not from {minimum_points} distinct UTC dates' 'seven daily restore-point gate'
Assert-Contains $text.BackupHealth 'repo1 and repo2 latest archived WAL identities differ' 'dual-repository WAL parity gate'
Assert-Contains $text.BackupHealth 'both repositories are behind PostgreSQL last archived WAL' 'dual-repository archived-WAL target gate'
Assert-Contains $text.BackupHealth 'walInventoryContinuityProvenByThisCheck' 'WAL inventory continuity non-claim'
