Assert-Contains $text.BackupAcceptance 'active_repo2_preflight = validate_active(' 'final receipt revalidates active repo2 approval/config'
Assert-Contains $text.BackupAcceptance 'isolatedRepo2PitrVerifiedSeparately' 'repo2 PITR evidence gate'
Assert-Contains $text.BackupAcceptance 'verified-flyway-checksums' 'root-installed signed Flyway inventory verifier'
Assert-Contains $text.BackupAcceptance 'live Flyway versions/scripts/checksums differ from the signed manifest' 'live database exact signed Flyway row gate'
Assert-Contains $text.BackupAcceptance 'restore receipt backup set differs from PITR acceptance' 'restore receipt backup-set binding'
Assert-Contains $text.BackupAcceptance 'def _fixed_sibling(' 'isolated acceptance sibling import'
Assert-Contains $text.BackupAcceptance 'evidenceReference": f"path={detail_path};sha256={detail_sha}"' 'narrow recovery receipt binds detailed evidence'
Assert-Contains $text.Repo2BackupUnit 'ExecStart=/usr/bin/python3 -I /usr/local/libexec/uten-imp-backup/locked_job.py repo2' 'repo2 fixed durable locked-job entrypoint'
Assert-Contains $text.BackupLockedJob 'REPO2_PREFLIGHT = (' 'repo2 preflight is fixed inside the locked job'
