Assert-Contains $text.Repo1BackupUnit 'OnFailure=uten-pgbackup-alert@%n.service' 'repo1 backup external alert wiring'
Assert-Contains $text.Repo1BackupUnit 'ExecStart=/usr/bin/python3 -I /usr/local/libexec/uten-imp-backup/locked_job.py repo1' 'repo1 fixed durable locked-job entrypoint'
