Assert-Contains $text.WheelhouseBuilder '--network none --read-only --cap-drop ALL' 'networkless least-privilege source-wheel build'
Assert-Contains $text.WheelhouseBuilder 'must run as an unprivileged host user and group' 'non-root wheelhouse builder identity'
