# Existing physical-replication guardrails are still part of the deployment contract.
Assert-Contains $text.PreparePrimary 'RECREATE_INVALID_SLOT="${RECREATE_INVALID_SLOT:-no}"' 'slot recreation defaults closed'
Assert-Contains $text.PreparePrimary 'pg_create_physical_replication_slot(' 'physical replication slot creation'
Assert-Contains $text.CloneReplica '--wal-method stream' 'streaming base backup'
